{
  "status": "SUPPORTED",
  "task_summary": "Identify compatible components, fasten them at a marked location, and leave the tool on the workbench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "fastening_location",
        "entity_kind": "FIXED_TARGET",
        "function": "The specific spot on the workbench where the fastening must occur.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["marked spot"],
        "required_properties": ["location for fastening"]
      },
      {
        "id": "compatible_component",
        "entity_kind": "OBJECT",
        "function": "Physical parts required to perform the fastening.",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["part", "block"],
        "required_properties": ["compatible with fastening location"]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "The implement used to secure the components.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screwdriver", "wrench", "drill"],
        "required_properties": ["capable of fastening"]
      },
      {
        "id": "workbench_surface",
        "entity_kind": "REGION",
        "function": "The surface where the tool must be left.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["tabletop"],
        "required_properties": ["surface for resting equipment"]
      },
      {
        "id": "storage_structure",
        "entity_kind": "REGION",
        "function": "Closed containers to be searched for missing components or tools.",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["cabinet", "drawer"],
        "required_properties": ["closed", "storage capable"]
      }
    ],
    "functional_relations": [
      {
        "id": "rel_1",
        "relation": "compatible_component fits fastening_location",
        "participant_roles": ["compatible_component", "fastening_location"]
      , 
      "required": true
      },
      {
        "id": "rel_2",
        "relation": "fastening_tool applies to compatible_component at fastening_location",
        "participant_roles": ["fastening_tool", "compatible_component", "fastening_location"]
      , 
      "required": true
      },
      {
        "id": "rel_3",
        "relation": "fastening_tool rests on workbench_surface",
        "participant_roles": ["fastening_tool", "workbench_surface"]
      , 
      "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "op_1",
        "operation": "identify_compatible_components",
        "participant_roles": ["compatible_component", "fastening_location"],
        "operation_count": 1
      },
      {
        "id": "op_2",
        "operation": "complete_fastening",
        "participant_roles": ["fastening_tool", "compatible_component", "fastening_location"],
        "operation_count": 1
      },
      {
        "id": "op_3",
        "operation": "deposit_tool",
        "participant_roles": ["fastening_tool", "workbench_surface"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "compatible_component": [
        {
          "label": "items on black tray",
          "visual_description": "Yellow rectangular objects on the workbench surface."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "blue_cabinet",
        "label": "Blue cabinet",
        "visual_description": "Closed cabinet door located behind the workbench.",
        "reason": "Potential storage for components or tools."
      },
      {
        "id": "desk_drawers",
        "label": "Desk drawers",
        "visual_description": "Closed drawers underneath the workbench.",
        "reason": "Potential storage for small components."
      }
    ],
    "inspection_order": [
      "blue_cabinet",
      "desk_drawers"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
